/**
 * nijo.xml の定数のうちテンプレート文字列のものについて、引数を埋め込む前の変換を種類ごとに定義する。
 * サーバー側の Core.AutoGenerated/ConstantTemplateKind.cs と同じ結果になるようにすること。
 */
export const ConstantTemplateKind = {
  /** 画面やログに出す文言に埋め込む値。変換しない。 */
  文言: (value: string): string => value,
  /** JSON の文字列リテラルの中に埋め込む値。引用符やバックスラッシュ、制御文字をエスケープする。 */
  JSON: (value: string): string => JSON.stringify(value).slice(1, -1),
}
